@lru_cache(None)
def filas(nombre):
    with (RAIZ / "results/informe_final" / nombre).open(encoding="utf-8", newline="") as f:
        return list(csv.DictReader(f))

def tolerancia(texto):
    return 0.5 * 10 ** (-len(texto.partition(".")[2]))

def construir_cifras():
    return [(ident, float(valor), tex, lambda nombre=nombre, fila=fila, col=col: (sum(int(r["particion"]) == fila for r in filas(nombre)) if col == "cantidad" else float(filas(nombre)[fila][col])))
            for ident, valor, tex, literal, nombre, fila, col in DECLARADAS]

def ejecutar(verboso=False):
    assert tolerancia("1.000") == 0.0005
    fallos = 0
    for (ident, declarado, tex, fn), (_, texto, _, literal, nombre, fila, col) in zip(construir_cifras(), DECLARADAS):
        obtenido = fn()
        contenido = (RAIZ / tex).read_text(encoding="utf-8")
        ok = literal in contenido and abs(obtenido - declarado) <= tolerancia(texto) + 1e-12
        fallos += not ok
        if verboso or not ok:
            print(f"{'OK' if ok else 'DISCREPA'} {ident}: escrito {texto}, calculado {obtenido:.9g} ({tex}; {nombre}, fila {fila + 2}, {col})")
    print(f"{len(DECLARADAS)} cifras del informe final, {len(DECLARADAS)-fallos} ok, {fallos} discrepan")
    return int(bool(fallos))

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--verboso", action="store_true")
    return ejecutar(ap.parse_args().verboso)

if __name__ == "__main__":
    raise SystemExit(main())
